/* Ocotillo theme: the OcotilloUI (NMBGMRDataManager) production palette.
   Tailwind blue/amber/red/orange/emerald/cyan over stone (light) and zinc
   (dark) neutrals.

   This is the default theme: it also matches <html> with no data-theme, so
   apps that never set one keep this look. Defines the whole token contract
   (see THEMING.md). */

:root:not([data-theme]),
:root[data-theme="ocotillo"] {
    /* OcotilloUI (NMBGMRDataManager) production palette — light.
       Tokens map MUI theme.ts to shadcn: tailwind blue/amber/red/orange/
       emerald/cyan + stone/slate neutrals. */
    --background: #e7e5e4;        /* stone-200 (page) */
    --foreground: #0f172a;        /* slate-900 */
    --card: #ffffff;              /* paper */
    --card-foreground: #0f172a;
    --popover: #ffffff;
    --popover-foreground: #0f172a;

    --primary: #1d4ed8;          /* blue-700 */
    --primary-foreground: #ffffff;
    --primary-light: #93c5fd;    /* blue-300 */
    --primary-dark: #1e3a8a;     /* blue-900 */

    --secondary: #d97706;        /* amber-600 */
    --secondary-foreground: #ffffff;
    --secondary-strong: #b45309; /* amber-700 */
    --secondary-dark: #92400e;   /* amber-800 */

    --muted: #f5f5f4;            /* stone-100 (wrapper) */
    --muted-foreground: #64748b; /* slate-500 */
    --accent: #f5f5f4;           /* stone-100 */
    --accent-foreground: #0f172a;
    --destructive: #dc2626;      /* red-600 */
    --warning-light: #fdba74;    /* orange-300 */
    --warning-dark: #c2410c;     /* orange-700 */

    --border: #d6d3d1;           /* stone-300 */
    --input: #d6d3d1;
    --ring: #1d4ed8;

    --chart-1: #1d4ed8;          /* blue-700 */
    --chart-2: #d97706;          /* amber-600 */
    --chart-3: #047857;          /* emerald-700 */
    --chart-4: #0891b2;          /* cyan-600 */
    --chart-5: #dc2626;          /* red-600 */

    --radius: 0.5rem;

    --sidebar: #ffffff;
    --sidebar-foreground: #0f172a;
    --sidebar-primary: #1d4ed8;
    --sidebar-primary-foreground: #ffffff;
    --sidebar-accent: #f5f5f4;
    --sidebar-accent-foreground: #0f172a;
    --sidebar-border: #d6d3d1;
    --sidebar-ring: #1d4ed8;

    --font-heading: 'Outfit Variable', system-ui, sans-serif;
    --font-sans: 'Public Sans Variable', system-ui, sans-serif;
}

:root:not([data-theme]).dark,
:root[data-theme="ocotillo"].dark {
    /* OcotilloUI production palette — dark (zinc neutrals). */
    --background: #18181b;        /* zinc-900 (default) */
    --foreground: #f1f5f9;        /* slate-100 */
    --card: #3f3f46;              /* zinc-700 (paper) */
    --card-foreground: #f1f5f9;
    --popover: #3f3f46;
    --popover-foreground: #f1f5f9;

    --primary: #2563eb;          /* blue-600 (brighter on dark) */
    --primary-foreground: #ffffff;
    --primary-light: #93c5fd;    /* blue-300 */
    --primary-dark: #1e3a8a;     /* blue-900 */

    --secondary: #d97706;        /* amber-600 */
    --secondary-foreground: #ffffff;
    --secondary-strong: #b45309; /* amber-700 */
    --secondary-dark: #92400e;   /* amber-800 */

    --muted: #27272a;            /* zinc-800 */
    --muted-foreground: #94a3b8; /* slate-400 */
    --accent: #27272a;           /* zinc-800 */
    --accent-foreground: #f1f5f9;
    --destructive: #ef4444;      /* red-500 (brighter on dark) */
    --warning-light: #fdba74;    /* orange-300 */
    --warning-dark: #c2410c;     /* orange-700 */

    --border: #3f3f46;           /* zinc-700 (divider) */
    --input: #3f3f46;
    --ring: #2563eb;

    --chart-1: #93c5fd;          /* blue-300 */
    --chart-2: #fcd34d;          /* amber-300 */
    --chart-3: #6ee7b7;          /* emerald-300 */
    --chart-4: #67e8f9;          /* cyan-300 */
    --chart-5: #fca5a5;          /* red-300 */

    --sidebar: #27272a;          /* zinc-800 */
    --sidebar-foreground: #f1f5f9;
    --sidebar-primary: #2563eb;
    --sidebar-primary-foreground: #ffffff;
    --sidebar-accent: #3f3f46;
    --sidebar-accent-foreground: #f1f5f9;
    --sidebar-border: #3f3f46;
    --sidebar-ring: #2563eb;
}
